'use strict';
(() => {
 let epoch=0,owner=null,users=[],offset=0,more=false;
 const $=selector=>document.querySelector(selector),esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 let hooks;
 function active(token){return token===epoch&&hooks.account.user?.id===owner&&hooks.account.isAdmin&&$('#sheet').open&&$('#sheet').dataset.panel==='admin'}
 function panel(title,html){hooks.openSheet(title,html);$('#sheet').dataset.panel='admin';$('#sheet').scrollTop=0}
 function list(){panel('用户管理','<h2>用户管理</h2><p class="admin-note">管理员可修改昵称、用户名和头像；账号状态与会员仍由私有管理表维护。</p><div>'+users.map(user=>'<button class="admin-user-row" data-admin-user="'+esc(user.id)+'"><span><strong translate="no">'+esc(user.display_name)+'</strong><small translate="no">@'+esc(user.handle)+'</small></span><span>编辑</span></button>').join('')+'</div>'+(more?'<button class="secondary-btn" id="admin-users-more">加载更多</button>':''))}
 function edit(id){const user=users.find(row=>row.id===id);if(!user)return;panel('编辑用户','<button class="text-button" id="admin-users-back">返回用户列表</button><h2 translate="no">'+esc(user.display_name)+'</h2><p class="admin-note" translate="no">'+esc(user.id)+'</p><form id="admin-user-form" data-user-id="'+esc(user.id)+'"><label class="form-field">昵称<input name="display_name" value="'+esc(user.display_name)+'" required maxlength="40"></label><label class="form-field">用户名<input name="handle" value="'+esc(user.handle)+'" pattern="[a-z0-9_]{3,24}" required maxlength="24"></label><label class="form-field">头像<select name="avatar_source"><option value="keep">保留当前头像</option><option value="remove">移除头像</option>'+users.filter(row=>row.avatar_path).map(row=>'<option value="'+esc(row.avatar_path)+'" translate="no">'+esc(row.display_name)+' · @'+esc(row.handle)+'</option>').join('')+'</select></label><p class="admin-note">选择现有头像时，服务器会复制到目标账号目录，不会修改来源用户的照片。</p><button class="primary-btn" type="submit">保存用户资料</button><p class="form-message" role="status"></p></form>')}
 async function load(append=false){const token=++epoch;owner=hooks.account.user?.id;if(!owner||!hooks.account.isAdmin){hooks.toast('仅管理员可操作。');return}panel('用户管理','<h2>用户管理</h2><p>正在加载…</p>');try{const result=await hooks.account.adminRequest({action:'list',offset:append?offset:0});if(!active(token))return;users=append?[...users,...result.users]:result.users;offset=result.offset+result.users.length;more=result.hasMore;list()}catch(error){if(active(token))panel('用户管理','<h2>用户管理暂不可用</h2><p>'+esc(error.message)+'</p><button class="secondary-btn" id="admin-users-retry">重试</button>')}}
 function init(value){hooks=value;
  document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.id==='manage-users'||button.id==='admin-users-retry')load();if(button.id==='admin-users-more')load(true);if(button.id==='admin-users-back')list();if(button.dataset.adminUser)edit(button.dataset.adminUser)});
  document.addEventListener('submit',async event=>{if(event.target.id!=='admin-user-form')return;event.preventDefault();const form=event.target,data=new FormData(form),button=form.querySelector('[type="submit"]'),message=form.querySelector('.form-message'),source=String(data.get('avatar_source')),token=epoch,id=form.dataset.userId;button.disabled=true;message.textContent='';try{const result=await hooks.account.adminRequest({action:'update',id,handle:String(data.get('handle')).trim().toLowerCase(),display_name:String(data.get('display_name')).trim(),avatar:source==='keep'||source==='remove'?{mode:source}:{mode:'copy',path:source}});if(!active(token)||!form.isConnected)return;const index=users.findIndex(row=>row.id===id);if(index>=0)users[index]=result.profile;if(id===hooks.account.user.id){await hooks.account.ensureProfile();if(!active(token))return;hooks.updateBadge()}message.textContent='用户资料已保存。'}catch(error){if(active(token)&&form.isConnected)message.textContent=error.message}finally{if(button.isConnected)button.disabled=false}});
  $('#sheet').addEventListener('close',()=>{if($('#sheet').dataset.panel==='admin'){epoch++;users=[];owner=null}});
  hooks.account.addEventListener('session',()=>{if(owner&&owner!==hooks.account.user?.id){epoch++;users=[];owner=null;if($('#sheet').dataset.panel==='admin'&&$('#sheet').open)$('#sheet').close()}});
 }
 globalThis.EchoAdminUsers=Object.freeze({init});
})();
